 &style.procedural;


 arrayfalsedatefmt_localtime
 IntlDateFormatterformatter
 stringstring
 intoffset&null;


 Convertit string en une valeur temporelle décomposée
 en champs (un &array; de divers champs), en commençant à
 offset et en consommant autant que possible de la
 chaîne d'entrée.

  &reftitle.examples;

   Exemple avec datefmt_localtime


<?php

$fmt = datefmt_create(
    'en_US',
    IntlDateFormatter::FULL,
    IntlDateFormatter::FULL,
    'America/Los_Angeles',
    IntlDateFormatter::GREGORIAN
);

$arr = datefmt_localtime($fmt, 'Wednesday, December 31, 1969 at 4:00:00 PM Pacific Standard Time', $offset);

echo 'Résultat de l\'analyse ';
if ($arr) {
    foreach ($arr as $key => $value) {
        echo "$key : $value , ";
    }
}

?>




   Exemple orienté objet


<?php

$fmt = new IntlDateFormatter(
    'en_US',
    IntlDateFormatter::FULL,
    IntlDateFormatter::FULL,
    'America/Los_Angeles',
    IntlDateFormatter::GREGORIAN
);

$arr = $fmt->localtime('Wednesday, December 31, 1969 at 4:00:00 PM Pacific Standard Time', $offset);

echo 'Résultat de l\'analyse ';
if ($arr) {
    foreach ($arr as $key => $value) {
        echo "$key : $value , ";
    }
}

?>



  &example.outputs;


Résultat de l'analyse tm_sec : 0 , tm_min : 0 , tm_hour : 16 , tm_year : 69 ,
